#!/usr/bin/env python3
# Batch 1: establishing views for the three directions of The Breath. Two camera variants each.
import os
R = '/home/user/workspace/r3/prompts'
HEAD = "A wide 16:9 landscape frame from a big-budget natural-history film about an alien world. It must read as real location photography, not artwork: {cam}, true lens perspective, fine physical surface detail, {haze}, slight film grain."
TAIL = "It must feel like a place you could walk into: firm ground in the foreground, a readable route into the middle distance, far landmarks dissolving in the air. Nothing posed, nothing glowing unless it is lit, no painterly brushwork, no illustration styling. No people, no buildings, no text, no watermark, no border."

B_PLACE = """THE PLACE. A tidal shelf on a cold, foggy coast at low tide, early morning. The shelf is the exposed lung of a creature the size of a mountain range that died ages ago: bone-white, porous and honeycombed like weathered coral limestone, tide-stained, streaked with droppings, crusted with orange lichen and draped in black-green weed. Set into the shelf are the open ends of its airways: enormous round throats twenty to fifty metres across, each with a thick rim of ivory cartilage built from stacked rings, like the cut end of a giant ribbed hose. Most are low broken collars a few metres high; two or three are leaning stumps several storeys tall with cracked, eroded edges. All of them are exhaling at the same moment: a dense column of cold white vapour pours up out of every throat and leans the same way on the wind."""
B_LAY_E = """LAYOUT, asymmetric, nothing centred. The nearest throat is close on the right, its wet rim filling the lower right third of the frame, the inner rings going down into darkness; its rim is crowded with a colony of crimson feathery gill-plumes, like the crowns of giant tube worms, the ones nearest the opening bent outward by the rush of air. From the bottom left a tide channel of pale teal seawater winds away across the shelf between the throats toward the horizon: the obvious route into the picture. A dozen more exhaling throats stand along that channel at different distances, each smaller and paler in the fog, the farthest only grey silhouettes with their columns. In the middle distance three tall pale animals on very long thin stilt legs, with small bodies, wade the channel, tiny beside the throats. A loose flock of hundreds of small dark flyers circles one distant column. Far off on the left, almost lost in fog, the open sea and the faint curve of one colossal rib rising from the water like a mountain."""
B_LAY_D = """LAYOUT, asymmetric, nothing centred. From this height the nearer throats are seen partly from above as dark ringed wells with vapour pouring out of them. The nearest one is low on the right, its rim crowded with a colony of crimson feathery gill-plumes, like the crowns of giant tube worms, bent outward by the rush of air. A tide channel of pale teal seawater starts at the bottom left and winds away across the shelf between the throats toward the horizon: the obvious route into the picture. A dozen more exhaling throats stand along that channel at different distances, each smaller and paler in the fog, the farthest only grey silhouettes with their columns. In the middle distance three tall pale animals on very long thin stilt legs, with small bodies, wade the channel, tiny beside the throats. A loose flock of hundreds of small dark flyers circles one distant column. Far off on the left, almost lost in fog, the open sea and the faint curve of one colossal rib rising from the water like a mountain."""
B_LIGHT = """LIGHT AND WEATHER. A low white sun behind thin sea fog, back left, rims the vapour columns with light and lays long soft reflections on the wet shelf; everything else is cool, muted and damp. Colours: ivory bone, wet black rock and weed, arterial crimson plumes, pale teal water, small patches of orange lichen. The mood is cold, quiet and lethal."""

A_PLACE = """THE PLACE. A warm, dripping cloud-forest gorge that has grown inside the collapsed lung of a creature the size of a mountain range that died ages ago. What stand here in place of trees are its airways: colossal hollow branching tubes of pale bone-white cartilage, ringed along their whole length like windpipes, forking again and again as they rise, the thickest wider than a house. Moss, ferns, hanging roots and epiphytes cover them. Instead of leaves their finest branches carry heavy clusters of translucent amber air sacs, each sac the size of a small car, thin-skinned and veined like a bladder, lit up where sun passes through them. Some sacs are venting: slow clouds of fine golden spore dust hang in the shafts of light."""
A_LAY_E = """LAYOUT, asymmetric, nothing centred. A shallow clear stream runs from the bottom right corner away up the gorge over mossy boulders: the obvious route into the picture. Close on the left, a fallen ringed airway lies half sunk in moss, its open hollow end, three metres across, facing the camera. In the middle distance one enormous ringed airway arches right over the stream like a natural bridge, sac clusters hanging beneath it, backlit. Under and beyond the arch the gorge opens into a brighter, misty clearing where more branching airways stand at different distances, each paler in the haze, and a thin waterfall falls from a honeycombed cliff far at the back. On the stream bank in the middle distance lies the carcass of a large six-legged grazing animal, furred over with moss and sprouting pale fruiting stalks. Small winged animals circle in the light at several distances."""
A_LAY_D = """LAYOUT, asymmetric, nothing centred. The shallow clear stream runs below, from the bottom right away up the gorge over mossy boulders: the obvious route into the picture. Low on the left, a fallen ringed airway lies half sunk in moss, its open hollow end visible. Ahead, one enormous ringed airway arches right over the stream like a natural bridge, sac clusters hanging beneath it, backlit; the camera is about to fly under it. Under and beyond the arch the gorge opens into a brighter, misty clearing where more branching airways stand at different distances, each paler in the haze, and a thin waterfall falls from a honeycombed cliff far at the back. On the stream bank below lies the carcass of a large six-legged grazing animal, furred over with moss and sprouting pale fruiting stalks. Small winged animals circle in the light at several distances."""
A_LIGHT = """LIGHT AND WEATHER. Low late-afternoon sun entering from the back right through gaps above, in separate shafts through wet air; warm gold in the light, deep green-black in the shade, every surface wet. Colours: deep moss green, pale bone, amber and gold. The mood is beautiful, close and lethal."""

C_PLACE = """THE PLACE. The last deep-blue light after dusk, inside the collapsed windpipe of a creature the size of a mountain range that died ages ago. It is now a gorge two hundred metres wide and open to the sky. Both walls are built from evenly spaced curved ribs of pale cartilage, ring after ring receding into the distance like the inside of a giant ribbed hose with its roof torn away; black moss and dripping water cover them. A slow river of fog fills the gorge floor and slides along it like breath. From the underside of every ring hang curtains of thousands of fine vertical threads strung with beads of sticky fluid, shining cold blue-green like glow-worm snares. Drifting through the air at several depths are large translucent bell-shaped animals trailing long thin tentacles, each lit faintly from inside, pale cyan with a small amber core. These living lights are the only light sources apart from the sky: they light the fog and the wet cartilage close to them and leave the rest in near darkness."""
C_LAY_E = """LAYOUT, asymmetric, nothing centred. The camera stands on a broad wet ledge on the left wall, a third of the way up, looking along the length of the gorge. The ledge continues ahead as a walkable shelf along the wall: the obvious route into the picture. Close on the right, one curtain of glowing threads hangs just beyond arm's reach, a small winged animal caught and wrapped in it. One floating bell-animal, about ten metres across, passes in the middle distance at eye level over the fog; four or five more are small points of light at increasing distances. Far away the gorge forks into two narrower branches. Above the walls is a strip of dark blue sky with a few stars and a band of last light near the horizon at the far end."""
C_LAY_D = """LAYOUT, asymmetric, nothing centred. The camera hovers just above the fog river, left of the middle of the gorge, looking along its length; the fog surface stretches away below like a road: the obvious route into the picture. Close on the right, one curtain of glowing threads hangs from the nearest ring, a small winged animal caught and wrapped in it. One floating bell-animal, about ten metres across, passes in the middle distance slightly above eye level; four or five more are small points of light at increasing distances. Far away the gorge forks into two narrower branches. Above the walls is a strip of dark blue sky with a few stars and a band of last light near the horizon at the far end."""
C_LIGHT = """LIGHT AND EXPOSURE. Exposed for the living lights, so most of the frame is dark: deep blue-black shadows, soft cyan and green pools of light on fog and wet surfaces, a few warm amber points. The glow falls off quickly and realistically; nothing is evenly lit. The mood is silent, beautiful and lethal."""

P = {
 'B-est-eye': (HEAD.format(cam="a large-format digital cinema camera with a 24 mm lens at standing height on wet rock, natural light only, deep focus", haze="sea haze building with distance"), B_PLACE, B_LAY_E, B_LIGHT),
 'B-est-drone': (HEAD.format(cam="a large-format digital cinema camera with a 35 mm lens on a drone about fifteen metres above the shelf, looking forward and slightly down along a tide channel, natural light only, deep focus", haze="sea haze building with distance"), B_PLACE, B_LAY_D, B_LIGHT),
 'A-est-eye': (HEAD.format(cam="a large-format digital cinema camera with a 24 mm lens at standing height on a wet boulder at the edge of a stream, natural light only, deep focus", haze="humid haze building with distance"), A_PLACE, A_LAY_E, A_LIGHT),
 'A-est-drone': (HEAD.format(cam="a large-format digital cinema camera with a 35 mm lens on a drone about ten metres above a stream, flying up a gorge beneath the canopy, natural light only, deep focus", haze="humid haze building with distance"), A_PLACE, A_LAY_D, A_LIGHT),
 'C-est-eye': (HEAD.format(cam="a large-format digital cinema camera with a fast 24 mm lens at high sensitivity, standing height on a wet ledge, available light only", haze="mist thickening with distance"), C_PLACE, C_LAY_E, C_LIGHT),
 'C-est-drone': (HEAD.format(cam="a large-format digital cinema camera with a fast 28 mm lens at high sensitivity on a slow drone, available light only", haze="mist thickening with distance"), C_PLACE, C_LAY_D, C_LIGHT),
}
for k, parts in P.items():
    open(f'{R}/{k}.txt', 'w').write('\n\n'.join(parts) + '\n\n' + TAIL + '\n')
    print(k, len('\n\n'.join(parts)) + len(TAIL))
